package com.example.payment.architecturetest;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.classes;

import com.tngtech.archunit.core.domain.JavaClasses;
import com.tngtech.archunit.core.importer.ClassFileImporter;
import com.tngtech.archunit.core.importer.ImportOption;
import com.tngtech.archunit.lang.ArchRule;
import com.tngtech.archunit.library.Architectures;
import org.junit.jupiter.api.Test;

/**
 * Keeps the layering intact: domain code must stay free of any technical
 * detail (frameworks, HTTP, JSON, file I/O, Spring, ...) so that a reviewer
 * skimming the middle of the business code never runs into infrastructure
 * concerns. Runs during `mvn verify` (payment-architecture-test module), not
 * as part of the fast `mvn test` unit suite.
 */
class LayerBoundariesTest {

    private static final String BASE_PACKAGE = "com.example.payment";

    private static final JavaClasses CLASSES = new ClassFileImporter()
            .withImportOption(ImportOption.Predefined.DO_NOT_INCLUDE_TESTS)
            .importPackages(BASE_PACKAGE);

    @Test
    void layers_only_talk_to_the_layer_below() {
        ArchRule rule = Architectures.layeredArchitecture()
                .consideringOnlyDependenciesInLayers()
                .layer("Domain").definedBy(BASE_PACKAGE + ".domain..")
                .layer("Application").definedBy(BASE_PACKAGE + ".application..")
                .layer("Infrastructure").definedBy(BASE_PACKAGE + ".infrastructure..")
                .layer("App").definedBy(BASE_PACKAGE + ".app..")
                .whereLayer("App").mayNotBeAccessedByAnyLayer()
                .whereLayer("Infrastructure").mayOnlyBeAccessedByLayers("App")
                .whereLayer("Application").mayOnlyBeAccessedByLayers("Infrastructure", "App")
                .whereLayer("Domain").mayOnlyBeAccessedByLayers("Application", "Infrastructure", "App");

        rule.check(CLASSES);
    }

    @Test
    void domain_code_does_not_depend_on_technical_frameworks() {
        ArchRule rule = classes()
                .that().resideInAPackage(BASE_PACKAGE + ".domain..")
                .should().onlyDependOnClassesThat()
                .resideOutsideOfPackages(
                        "org.springframework..",
                        "com.fasterxml.jackson..",
                        "java.nio.file..",
                        "java.io..",
                        "java.net..",
                        "javax.sql..",
                        "java.sql..")
                .because("domain (business) code must not reference technical/infrastructure details");

        rule.check(CLASSES);
    }

    @Test
    void application_code_does_not_depend_on_technical_frameworks() {
        ArchRule rule = classes()
                .that().resideInAPackage(BASE_PACKAGE + ".application..")
                .should().onlyDependOnClassesThat()
                .resideOutsideOfPackages(
                        "org.springframework..",
                        "com.fasterxml.jackson..",
                        "java.nio.file..",
                        "java.net..",
                        "javax.sql..",
                        "java.sql..")
                .because("application (use-case) code must not leak technical details from infrastructure");

        rule.check(CLASSES);
    }
}
